/// Returns the members an appointment can be booked for: always self,
/// plus minors (age < 18) when the current user is the Family Head.
List<Member> bookableMembers({
  required List<Member> allMembers,
  required String? activeMemberId,
  required bool isHead,
}) {
  final self = allMembers.where((m) => m.id == activeMemberId);
  if (!isHead) return self.toList(growable: false);

  bool isMinor(Member member) {
    final dob = member.dateOfBirth;
    if (dob == null) return false;
    final parsed = DateTime.tryParse(dob);
    if (parsed == null) return false;
    final now = DateTime.now();
    var age = now.year - parsed.year;
    if (now.month < parsed.month ||
        (now.month == parsed.month && now.day < parsed.day)) {
      age -= 1;
    }
    return age < 18;
  }

  final seen = <String>{};
  final result = <Member>[];
  for (final member in [...self, ...allMembers.where(isMinor)]) {
    if (seen.add(member.id)) result.add(member);
  }
  return result;
}

String _memberLabel(Member member, bool isHead) {
  if (member.relationshipLabel.toLowerCase() == 'head' || isHead) {
    return '${member.displayName} (Family Head)';
  }
  final dob = member.dateOfBirth;
  if (dob != null) {
    final parsed = DateTime.tryParse(dob);
    if (parsed != null) {
      final now = DateTime.now();
      var age = now.year - parsed.year;
      if (now.month < parsed.month ||
          (now.month == parsed.month && now.day < parsed.day)) {
        age -= 1;
      }
      if (age < 18) return '${member.displayName} (Minor)';
    }
  }
  return member.displayName;
}

class BookAppointmentScreen extends ConsumerStatefulWidget {
  const BookAppointmentScreen({super.key});

  @override
  ConsumerState<BookAppointmentScreen> createState() =>
      _BookAppointmentScreenState();
}

class _BookAppointmentScreenState extends ConsumerState<BookAppointmentScreen> {
  final _reasonController = TextEditingController();
  String? _selectedMemberId;
  DateTime? _selectedSlot;
  int _durationMinutes = 30;
  ReportAttachment? _attachment;
  bool _submitting = false;

  @override
  void dispose() {
    _reasonController.dispose();
    super.dispose();
  }

  Future<void> _submit(bool hasDoctor) async {
    if (!hasDoctor) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text(
            'A family doctor must be assigned before requesting an appointment.',
          ),
          backgroundColor: AppColors.danger,
        ),
      );
      return;
    }

    final memberId = _selectedMemberId;
    final profileId = ref.read(activeMemberProvider);
    final startsAt = _selectedSlot;
    final reason = _reasonController.text.trim();
    final attachment = _attachment;
    if (memberId == null || startsAt == null || reason.isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text(
            'Please choose a member, date, time and reason for visit.',
          ),
          backgroundColor: AppColors.warning,
        ),
      );
      return;
    }
    setState(() => _submitting = true);
    try {
      await ref
          .read(familyPortalApiProvider)
          .bookAppointment(
            memberId: memberId,
            startsAt: startsAt,
            durationMinutes: _durationMinutes,
            reason: reason,
          );
      ref.invalidate(myAppointmentsProvider);
      await _uploadAttachment(memberId, attachment, profileId);
      if (mounted && ref.read(activeMemberProvider) == profileId) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(
            content: Text(
              'Appointment requested. You will be notified once confirmed.',
            ),
            backgroundColor: AppColors.success,
          ),
        );
        Navigator.of(context).pop(true);
      }
    } on Object {
      if (mounted && ref.read(activeMemberProvider) == profileId) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(
            content: Text(
              'Could not book the appointment. A family doctor must be assigned first.',
            ),
            backgroundColor: AppColors.danger,
          ),
        );
      }
    } finally {
      if (mounted) setState(() => _submitting = false);
    }
  }

  /// Runs only after the booking exists; a failed upload is reported, never hidden.
  Future<void> _uploadAttachment(
    String memberId,
    ReportAttachment? attachment,
    String? profileId,
  ) async {
    if (attachment == null ||
        !mounted ||
        ref.read(activeMemberProvider) != profileId) {
      return;
    }
    final messenger = ScaffoldMessenger.of(context);
    try {
      await ref
          .read(mobileApiProvider)
          .uploadLabReport(memberId: memberId, path: attachment.path);
      ref.invalidate(memberLabReportsProvider);
    } on Object {
      messenger.showSnackBar(
        const SnackBar(
          content: Text(
            'Appointment requested, but the attachment could not be uploaded. Add it from Upload lab report.',
          ),
          backgroundColor: AppColors.warning,
        ),
      );
    }
  }

  void _showMessage(String message) => ScaffoldMessenger.of(
    context,
  ).showSnackBar(SnackBar(content: Text(message)));

  @override
  Widget build(BuildContext context) {
    ref.listen<String?>(activeMemberProvider, (previous, next) {
      if (previous != next) {
        setState(() {
          _selectedMemberId = next;
          _selectedSlot = null;
          _reasonController.clear();
          _attachment = null;
        });
      }
    });
    ref.listen(familyDashboardProvider, (previous, next) {
      if (previous?.valueOrNull?.familyDoctor?.id !=
          next.valueOrNull?.familyDoctor?.id) {
        setState(() => _selectedSlot = null);
      }
    });
    final familyDoctor = ref
        .watch(familyDashboardProvider)
        .valueOrNull
        ?.familyDoctor;
    final activeMemberId = ref.watch(activeMemberProvider);
    final membersAsync = ref.watch(membersProvider);
    final isHead = ref.watch(isFamilyHeadProvider).valueOrNull ?? false;
    final isDark = Theme.of(context).brightness == Brightness.dark;
    final primaryColor = isDark ? AppColors.primaryLumDark : AppColors.primary;

    _selectedMemberId ??= activeMemberId;

    return Scaffold(
      appBar: AppBar(
        title: const Text(
          'Book appointment',
          style: TextStyle(fontWeight: FontWeight.w700),
        ),
        elevation: 0,
      ),
      body: SafeArea(
        child: membersAsync.when(
